class MemoryBlankNodeIdentityProbeTest {
	@Test
	void nestedOnlyIdentityIsReservedWithoutSelfRegistration() {
		var vf = new MemValueFactory();
		var plain = SimpleValueFactory.getInstance();
		var nested = vf.createTripleTerm(plain.createBNode("scope-0"), plain.createIRI("urn:p"),
				plain.createLiteral("nested"));
		BNodeIdResolver resolver = assertInstanceOf(BNodeIdResolver.class, vf);
		assertTrue(resolver.hasBNodeId("scope-0"));
		assertFalse(resolver.hasBNodeId("absent"));
		assertNull(vf.getMemBNode(plain.createBNode("absent")), "membership checks must not register candidates");
		var scope = new BlankNodeAllocationScope("scope-", null);
		scope.reserve("fixed");
		assertEquals("scope-1", scope.createBNode(vf).getID());
		assertEquals("scope-2", scope.createBNode(vf).getID());
		assertNotNull(nested.getSubject());
	}
}
